#!/usr/bin/env node
/**
 * Server i18n catalog generator.
 *
 * The app's ARB files (lib/l10n/app_*.arb) are the single source of truth for
 * every text the SERVER writes into notification docs / pushes. This script
 * copies the keys listed in src/shared/i18n/serverKeys.json out of the ARBs
 * into two generated files:
 *
 *   functions/src/shared/i18n/catalog.generated.ts
 *       the server-side catalog used by t() (push texts, stored English
 *       fallbacks) - Cloud Functions are deployed without lib/, so the
 *       strings have to live inside functions/.
 *   lib/core/utils/server_text.dart
 *       serverText(l10n, key, params): resolves a stored `titleKey` /
 *       `bodyKey` / `textKey` + `params` through AppLocalizations on the
 *       client.
 *
 * Usage (from functions/):  node scripts/gen-i18n-catalog.cjs
 * Then `flutter gen-l10n` at the repo root if the ARBs changed.
 * __tests__/unit/i18nCatalog.test.ts fails when the generated catalog drifts
 * from the ARBs, so re-run this after editing a server key's translation.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const FUNCTIONS_DIR = path.resolve(__dirname, '..');
const REPO_ROOT = path.resolve(FUNCTIONS_DIR, '..');
const ARB_DIR = path.join(REPO_ROOT, 'lib', 'l10n');
const KEYS_FILE = path.join(FUNCTIONS_DIR, 'src', 'shared', 'i18n', 'serverKeys.json');
const TS_OUT = path.join(FUNCTIONS_DIR, 'src', 'shared', 'i18n', 'catalog.generated.ts');
const DART_OUT = path.join(REPO_ROOT, 'lib', 'core', 'utils', 'server_text.dart');

const LOCALES = ['en', 'de', 'es', 'fr', 'it', 'pt', 'pt_BR'];

function loadArb(locale) {
  const file = path.join(ARB_DIR, `app_${locale}.arb`);
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function fail(msg) {
  console.error(`gen-i18n-catalog: ${msg}`);
  process.exit(1);
}

const keys = JSON.parse(fs.readFileSync(KEYS_FILE, 'utf8'));
if (!Array.isArray(keys) || keys.some((k) => typeof k !== 'string')) {
  fail('serverKeys.json must be an array of ARB keys');
}
const unique = [...new Set(keys)].sort();
if (unique.length !== keys.length) fail('serverKeys.json has duplicate keys');

const arbs = Object.fromEntries(LOCALES.map((l) => [l, loadArb(l)]));
for (const key of unique) {
  for (const l of LOCALES) {
    if (typeof arbs[l][key] !== 'string') fail(`"${key}" missing from app_${l}.arb`);
  }
}

// ---------------------------------------------------------------- TypeScript
const ts = [];
ts.push('/* eslint-disable */');
ts.push('// GENERATED by functions/scripts/gen-i18n-catalog.cjs from lib/l10n/app_*.arb.');
ts.push('// Do not edit by hand: change the ARB files, then re-run the script.');
ts.push("import type { AppLocale } from './locales';");
ts.push('');
ts.push('export type ArbKey =');
unique.forEach((k, i) => ts.push(`  | '${k}'${i === unique.length - 1 ? ';' : ''}`));
ts.push('');
ts.push('export const ARB_KEYS: readonly ArbKey[] = [');
unique.forEach((k) => ts.push(`  '${k}',`));
ts.push('];');
ts.push('');
ts.push('export const ARB_CATALOG: Record<AppLocale, Record<ArbKey, string>> = {');
for (const l of LOCALES) {
  ts.push(`  ${l}: {`);
  for (const k of unique) ts.push(`    ${k}: ${JSON.stringify(arbs[l][k])},`);
  ts.push('  },');
}
ts.push('};');
ts.push('');
fs.writeFileSync(TS_OUT, ts.join('\n'), 'utf8');

// ---------------------------------------------------------------------- Dart
function placeholdersOf(key) {
  const meta = arbs.en[`@${key}`];
  const ph = meta && meta.placeholders ? meta.placeholders : null;
  const usesBraces = /\{[A-Za-z_][A-Za-z0-9_]*[,}]/.test(arbs.en[key]);
  if (!ph) {
    if (usesBraces) fail(`"${key}" has placeholders but no @${key}.placeholders metadata in app_en.arb`);
    return [];
  }
  return Object.entries(ph).map(([name, def]) => ({ name, type: (def && def.type) || 'Object' }));
}

const used = new Set();
const dart = [];
dart.push('// GENERATED by functions/scripts/gen-i18n-catalog.cjs from lib/l10n/app_*.arb');
dart.push('// and functions/src/shared/i18n/serverKeys.json. Do not edit by hand.');
dart.push('');
dart.push("import '../../generated/app_localizations.dart';");
dart.push('');
dart.push('/// Renders a text the SERVER stored as a key + params (notification');
dart.push('/// `titleKey` / `bodyKey` + `params`, system message `textKey`) in the');
dart.push('/// viewer\'s language. Returns null for an unknown key (e.g. a key added by');
dart.push('/// a newer server than this app version) so the caller falls back to the');
dart.push('/// stored English text.');
dart.push('String? serverText(');
dart.push('  AppLocalizations l10n,');
dart.push('  String? key, [');
dart.push('  Map<String, dynamic>? params,');
dart.push(']) {');
dart.push('  if (key == null || key.isEmpty) return null;');
dart.push('  final p = params ?? const <String, dynamic>{};');
dart.push('  switch (key) {');
for (const k of unique) {
  const ph = placeholdersOf(k);
  if (ph.length === 0) {
    dart.push(`    case '${k}':`);
    dart.push(`      return l10n.${k};`);
  } else {
    const args = ph
      .map((x) => {
        if (x.type === 'int') { used.add('int'); return `_int(p['${x.name}'])`; }
        if (x.type === 'num' || x.type === 'double') { used.add('num'); return `_num(p['${x.name}'])`; }
        used.add('str');
        return `_str(p['${x.name}'])`;
      })
      .join(', ');
    dart.push(`    case '${k}':`);
    dart.push(`      return l10n.${k}(${args});`);
  }
}
dart.push('    default:');
dart.push('      return null;');
dart.push('  }');
dart.push('}');
dart.push('');
if (used.has('str')) {
  dart.push("String _str(Object? v) => v == null ? '' : v.toString();");
  dart.push('');
}
if (used.has('int')) {
  dart.push('int _int(Object? v) {');
  dart.push('  if (v is num) return v.toInt();');
  dart.push("  return int.tryParse('${v ?? ''}') ?? 0;");
  dart.push('}');
  dart.push('');
}
if (used.has('num')) {
  dart.push('num _num(Object? v) {');
  dart.push('  if (v is num) return v;');
  dart.push("  return num.tryParse('${v ?? ''}') ?? 0;");
  dart.push('}');
  dart.push('');
}
fs.writeFileSync(DART_OUT, dart.join('\n'), 'utf8');

console.log(`gen-i18n-catalog: ${unique.length} keys x ${LOCALES.length} locales`);
console.log(`  -> ${path.relative(REPO_ROOT, TS_OUT)}`);
console.log(`  -> ${path.relative(REPO_ROOT, DART_OUT)}`);
